script:
(function () {
  'use strict';
  // IRA spend it or save it. A windfall (once, or every year) is spent, or put into a traditional
  // or a Roth IRA up to the room left under the 2026 limit for your age (the rest is spent).
  // Contributions go in at the start of the year and grow at the expected return:
  //   balance = (balance + c) x (1 + r)
  // Traditional: tax saved now = c x current tax rate (if deductible); after tax at retirement =
  //   balance - retirement tax x (balance - nondeductible contributions). Roth: balance, tax-free.
  // Cash to spend now: spend = amount; traditional = amount - c + tax saved; Roth = amount - c.
  // Today's dollars = value / (1 + inflation)^years.
  // CHECKS (Node, scratch tests): $3,000 at 6% for 30 years = 3,000 x 1.06^30 = $17,230.47; after
  // 20% tax = $13,784.38; tax saved at 27% = $810; $3,000 a year for 30 years at 6% (start of
  // year) = 3,000 x 1.06 x (1.06^30 - 1) / 0.06 = $251,405.03; $10,000 at age 35 with $0 already
  // in -> $7,500 in the IRA, $2,500 spent; age 50 -> $8,600; nondeductible $3,000 at 0% return
  // -> after tax = $3,000; 0% return -> balance = sum of contributions.
  // ---- 2026 IRA limits (IRS Notice 2025-67, tax year 2026) -----------------------------------
  var IRA = {
    year: 2026,
    limit: 7500,     // IRC 219(b)(5) contribution limit, traditional and Roth combined
    catchUp50: 1100  // additional catch-up from age 50
  };
  // -----------------------------------------------------------------------------------------------

  function ageLimit(age) { return IRA.limit + (age >= 50 ? IRA.catchUp50 : 0); }

  // p: amount, repeat, age, retireAge, already, taxNow, taxLater, rate, inflation, deductible
  function compare(p) {
    var n = p.retireAge - p.age, bal = 0, nonded = 0, rows = [], capped = false;
    var t = { amount: 0, c: 0, saved: 0 };
    for (var y = 0; y < n; y++) {
      var age = p.age + y;
      var amt = (p.repeat || y === 0) ? p.amount : 0;
      var room = Math.max(0, ageLimit(age) - p.already);
      var c = Math.min(amt, room);
      if (amt > room + 0.005) capped = true;
      bal = (bal + c) * (1 + p.rate);
      if (!p.deductible) nonded += c;
      t.amount += amt; t.c += c; t.saved += p.deductible ? c * p.taxNow : 0;
      rows.push({ age: age, c: c, trad: bal - p.taxLater * Math.max(0, bal - nonded), roth: bal });
    }
    var real = Math.pow(1 + p.inflation, n);
    var tradAfter = bal - p.taxLater * Math.max(0, bal - nonded);
    return { n: n, bal: bal, tradAfter: tradAfter, real: real, t: t, rows: rows, capped: capped };
  }

  var moneyFmt = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var money = { format: function (x) { return moneyFmt.format(Math.abs(x) < 0.005 || !isFinite(x) ? 0 : x); } };

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function fillRows(id, rows) {
    var body = document.getElementById(id);
    body.textContent = '';
    rows.forEach(function (row) {
      var tr = document.createElement('tr');
      row.forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  function update() {
    var amount = num('isAmount'), age = Math.round(num('isAge')), retireAge = Math.round(num('isRetireAge')),
        already = num('isAlready'), taxNow = num('isTaxNow'), taxLater = num('isTaxLater'), rate = num('isReturn'),
        inflation = num('isInflation'), repeat = document.getElementById('isRepeat').checked,
        deductible = document.getElementById('isDeductible').checked;
    var error = document.getElementById('isError');
    var bad = [amount, age, retireAge, already, taxNow, taxLater, rate, inflation].some(isNaN) || amount < 0 ||
              age < 16 || age > 99 || retireAge <= age || retireAge > 100 || already < 0 || taxNow < 0 ||
              taxNow > 60 || taxLater < 0 || taxLater > 60 || rate < 0 || rate > 20 || inflation < 0 || inflation > 15;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter non-negative amounts, an age from 16 to 99 with a retirement age above it (up to 100), ' +
                          'tax rates up to 60%, a return up to 20% and inflation up to 15%.';
      return;
    }
    var r = compare({ amount: amount, repeat: repeat, age: age, retireAge: retireAge, already: already,
                      taxNow: taxNow / 100, taxLater: taxLater / 100, rate: rate / 100, inflation: inflation / 100,
                      deductible: deductible });
    var t = r.t;
    set('isRothLabel', 'Roth IRA at age ' + retireAge + ', tax-free');
    set('isRothValue', money.format(r.bal));
    set('isTradAfter', money.format(r.tradAfter));
    set('isTradSaved', money.format(t.saved));
    set('isSpendCash', money.format(t.amount));

    if (t.c <= 0) {
      set('isSummary', amount > 0 ? 'You have no room left under the ' + IRA.year + ' IRA limit, so none of this money can go into an IRA this year.'
                                  : 'Enter the amount you could spend or save.');
      set('isBetter', '');
    } else {
      set('isSummary', 'Putting ' + money.format(t.c) + (repeat ? ' into an IRA over ' + r.n + ' years' : ' into an IRA now') +
          ' instead of spending it grows to about ' + money.format(r.bal) + ' by age ' + retireAge + ', worth ' +
          money.format(r.bal / r.real) + " in today's dollars.");
      var better;
      if (!deductible) {
        better = 'With no deduction, the Roth IRA comes out ahead: the same contribution grows tax-free instead of having its growth taxed.';
      } else if (Math.abs(taxNow - taxLater) < 1e-9) {
        better = 'With the same tax rate now and later, a traditional and a Roth IRA leave the same amount for each dollar of take-home pay you put in. The traditional IRA also gives you ' +
                 money.format(t.saved) + ' of tax savings now.';
      } else if (taxLater < taxNow) {
        better = 'Your tax rate in retirement is lower than now, so a traditional IRA leaves more for each dollar of take-home pay you put in, as long as you also save the ' +
                 money.format(t.saved) + ' of tax it saves you.';
      } else {
        better = 'Your tax rate in retirement is higher than now, so a Roth IRA leaves more for each dollar of take-home pay you put in.';
      }
      set('isBetter', better);
    }
    var capNote = document.getElementById('isCapped');
    capNote.hidden = !r.capped;
    if (r.capped) capNote.textContent = 'Part of this money is above your remaining room under the ' + IRA.year +
      ' IRA limit ($' + IRA.limit.toLocaleString('en-US') + ', or $' + (IRA.limit + IRA.catchUp50).toLocaleString('en-US') +
      ' from age 50), so that part is counted as spent.';

    fillRows('isCompare', [
      ['Put in the IRA', money.format(0), money.format(t.c), money.format(t.c)],
      ['Tax saved now', money.format(0), money.format(t.saved), money.format(0)],
      [repeat ? 'Cash to spend, all years' : 'Cash to spend now', money.format(t.amount), money.format(t.amount - t.c + t.saved), money.format(t.amount - t.c)],
      ['Value at age ' + retireAge, money.format(0), money.format(r.bal), money.format(r.bal)],
      ['After tax at age ' + retireAge, money.format(0), money.format(r.tradAfter), money.format(r.bal)],
      ["After tax, today's dollars", money.format(0), money.format(r.tradAfter / r.real), money.format(r.bal / r.real)]
    ]);
    fillRows('isSchedule', r.rows.map(function (row) {
      return [row.age, money.format(row.c), money.format(row.trad), money.format(row.roth)];
    }));
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('isForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
